": "ديكستروميثورفان (Dextromethorphan) - سعال جاف", "e": "Dextromethorphan - Dry Cough", "ga": "أطفال فوق 6 سنوات وبالغين فقط", "ge": "Children over 6 years and adults only", "mw": null, "dt": "حسب عمر/وزن المنتج", "wb": false, "lo": null, "hi": null, "ms": null, "md": null, "mdk": null, "fa": "كل 6-8 ساعات", "fe": "Every 6-8 hours", "wa": "يُمنع منعاً باتاً تحت سن 6 سنوات (توصية FDA/أغلب الهيئات الصحية)", "we": "Strictly contraindicated under 6 years (FDA/most health authorities recommendation)", "rx": false, "n": "Imported from prototype; awaiting pharmacist review."}, {"a": "غوايفينيزين (Guaifenesin) - سعال مع بلغم", "e": "Guaifenesin - Productive Cough", "ga": "أطفال فوق 6 سنوات وبالغين فقط", "ge": "Children over 6 years and adults only", "mw": null, "dt": "حسب عمر/وزن المنتج", "wb": false, "lo": null, "hi": null, "ms": null, "md": null, "mdk": null, "fa": "كل 4 ساعات", "fe": "Every 4 hours", "wa": "يُمنع تحت سن 6 سنوات، مع سوائل كافية لتسهيل طرد البلغم", "we": "Contraindicated under 6 years, with adequate fluids to ease expectoration", "rx": false, "n": "Imported from prototype; awaiting pharmacist review."}, {"a": "عسل نحل (Honey) - للسعال", "e": "Honey - For Cough", "ga": "أطفال فوق سنة واحدة فقط", "ge": "Children over 1 year only", "mw": null, "dt": "2.5-5 مل (جرعة ثابتة)", "wb": false, "lo": null, "hi": null, "ms": null, "md": null, "mdk": null, "fa": "عند الحاجة، خصوصاً قبل النوم", "fe": "As needed, especially before bed", "wa": "ممنوع منعاً باتاً تحت سنة واحدة (خطر التسمم الوشيقي - Botulism)", "we": "Strictly prohibited under 1 year (risk of infant botulism)", "rx": false, "n": "CORRECTED 4 Nov: fixed 2.5-5 ml dose (was wrongly calculated per kg). Confirm."}, {"a": "سيميثيكون نقط (Simethicone) - مغص الرضع", "e": "Simethicone Drops - Infant Colic", "ga": "رضع", "ge": "Infants", "mw": null, "dt": "0.3 مل (20 ملغم) لكل جرعة", "wb": false, "lo": null, "hi": null, "ms": null, "md": null, "mdk": null, "fa": "بعد كل رضعة عند الحاجة، حتى 4 مرات يومياً", "fe": "After each feed as needed, up to 4 times daily", "wa": "أدلة الفعالية محدودة علمياً، آمن نسبياً لكن ليس علاجاً مؤكداً لمغص الرضع", "we": "Limited scientific evidence of efficacy, relatively safe but not a proven treatment for infant colic", "rx": false, "n": "Imported from prototype; awaiting pharmacist review."}, {"a": "أونداسيترون (Ondansetron) - أطفال", "e": "Ondansetron - Children", "ga": "أطفال فوق 6 أشهر (حسب تقييم الطبيب)", "ge": "Children over 6 months (per doctor assessment)", "mw": 8, "dt": "0.15 ملغم/كغم/جرعة", "wb": true, "lo": 0.15, "hi": 0.15, "ms": 8, "md": null, "mdk": null, "fa": "جرعة واحدة غالباً، لا تكرر إلا بإشراف طبي", "fe": "Usually single dose, do not repeat without medical supervision", "wa": "يوصف من طبيب فقط لحالات القيء المستمر (مثل التهاب المعدة والأمعاء)، حذر مع أمراض القلب النادرة (إطالة QT)", "we": "Prescribed by doctor only for persistent vomiting (e.g. gastroenteritis), caution with rare heart conditions (QT prolongation)", "rx": true, "n": "CORRECTED 4 Nov: now calculated as 0.15 mg/kg per dose, max 8 mg. Confirm."}, {"a": "أونداسيترون (Ondansetron) - بالغين", "e": "Ondansetron - Adults", "ga": "بالغين", "ge": "Adults", "mw": 40, "dt": "4-8 ملغم/جرعة ثابتة", "wb": false, "lo": null, "hi": null, "ms": 8, "md": 24, "mdk": null, "fa": "كل 8 ساعات حسب وصف الطبيب", "fe": "Every 8 hours as prescribed", "wa": "يتطلب تقييم طبي، حذر مع أمراض القلب", "we": "Requires medical assessment, caution with heart disease", "rx": true, "n": "Imported from prototype; awaiting pharmacist review."}, {"a": "ميتوكلوبراميد (Metoclopramide)", "e": "Metoclopramide", "ga": "أطفال وبالغين (بحذر شديد عند الأطفال)", "ge": "Children and adults (extreme caution in children)", "mw": null, "dt": "0.1-0.15 ملغم/كغم/جرعة", "wb": true, "lo": 0.1, "hi": 0.15, "ms": 10, "md": 30, "mdk": null, "fa": "حسب وصف الطبيب فقط", "fe": "As prescribed by doctor only", "wa": "خطر آثار جانبية خارج هرمية (حركات لا إرادية) خصوصاً عند الأطفال، لا يُستخدم إلا بإشراف طبيب مباشر", "we": "Risk of extrapyramidal side effects (involuntary movements) especially in children, only used under direct doctor supervision", "rx": true, "n": "CHECK: daily max 30 mg looks like the adult figure but record covers children."}, {"a": "ديمينهيدرينات (Dimenhydrinate) - دوار الحركة", "e": "Dimenhydrinate - Motion Sickness", "ga": "أطفال فوق سنتين وبالغين", "ge": "Children over 2 years and adults", "mw": null, "dt": "1-1.5 ملغم/كغم/جرعة", "wb": true, "lo": 1.0, "hi": 1.5, "ms": 50, "md": 300, "mdk": null, "fa": "كل 6-8 ساعات", "fe": "Every 6-8 hours", "wa": "يسبب نعاساً، يُستخدم أساساً لدوار الحركة وليس القيء الناتج عن عدوى معوية", "we": "Causes drowsiness, used mainly for motion sickness not gastroenteritis-related vomiting", "rx": false, "n": "CHECK: daily max 300 mg looks like the adult figure but record covers children over 2."}, {"a": "سيتيريزين (Cetirizine) - أطفال 6-11 سنة", "e": "Cetirizine - Children 6-11 years", "ga": "أطفال 6-11 سنة", "ge": "Children 6-11 years", "mw": null, "dt": "5 ملغم/جرعة ثابتة", "wb": false, "lo": null, "hi": null, "ms": 5, "md": 10, "mdk": null, "fa": "مرتين يومياً", "fe": "Twice daily", "wa": "قد يسبب نعاساً خفيفاً", "we": "May cause mild drowsiness", "rx": false, "n": "Imported from prototype; awaiting pharmacist review."}]') as t(a text, e text, ga text, ge text, mw numeric, dt text, wb boolean, lo numeric, hi numeric, ms numeric, md numeric, mdk numeric, fa text, fe text, wa text, we text, rx boolean, n text);
