select b, a, e, ga, ge, sa, se, ra, re, 'Imported from prototype; awaiting pharmacist review.' from jsonb_to_recordset('[{"b": "head", "a": "صداع (Headache)", "e": "Headache", "ga": "أطفال وبالغين", "ge": "Children and adults", "sa": "باراسيتامول أو إيبوبروفين حسب الوزن/العمر مع الراحة في غرفة مظلمة وشرب سوائل كافية", "se": "Paracetamol or Ibuprofen based on weight/age, rest in a dark quiet room, and adequate fluids", "ra": "أسوأ صداع بالحياة بشكل مفاجئ، صداع مع حمى وتيبس رقبة وطفح جلدي، صداع بعد إصابة رأس، تغير بالرؤية أو الوعي", "re": "Sudden worst headache of life, headache with fever and neck stiffness and rash, headache after head injury, vision or consciousness changes"}, {"b": "head", "a": "دوخة ودوار (Dizziness & Vertigo)", "e": "Dizziness & Vertigo", "ga": "بالغين وأطفال فوق سنتين", "ge": "Adults and children over 2 years", "sa": "الراحة وتجنب الحركات المفاجئة وشرب سوائل كافية. لدوار الحركة والسفر يمكن استخدام ديمينهيدرينات حسب الوزن والجرعة", "se": "Rest, avoid sudden posture changes, stay hydrated. For motion sickness, Dimenhydrinate may be used based on weight/age", "ra": "دوخة مفاجئة شديدة مصحوبة بضعف بالوجه أو الأطراف، تلعثم بالكلام، فقدان وعي، أو طنين حاد مع فقدان توازن (اشتباه سكتة دماغية طارئة)", "re": "Sudden severe dizziness with facial/limb weakness, slurred speech, fainting, or acute tinnitus with ataxia (suspected stroke)"}, {"b": "head", "a": "حساسية العيون (Eye Allergy)", "e": "Eye Allergy", "ga": "جميع الأعمار", "ge": "All ages", "sa": "كمادات باردة + قطرات عين مضادة للهيستامين + تجنب فرك العين", "se": "Cold compresses + antihistamine eye drops + avoid rubbing eyes", "ra": "ألم شديد بالعين، تغير بالرؤية، إفرازات صديدية، تورم شديد بجفن واحد", "re": "Severe eye pain, vision changes, purulent discharge, severe swelling of one eyelid"}, {"b": "head", "a": "حساسية الأنف (Allergic Rhinitis)", "e": "Allergic Rhinitis", "ga": "أطفال فوق سنتين وبالغين", "ge": "Children over 2 years and adults", "sa": "مضاد هيستامين فموي (لوراتادين/سيتيريزين) + بخاخ أنف فلوتيكازون للحالات المزمنة + محلول ملحي للأنف", "se": "Oral antihistamine (Loratadine/Cetirizine) + Fluticasone nasal spray for chronic cases + saline nasal solution", "ra": "نزيف أنفي متكرر شديد، صعوبة تنفس، تورم بالوجه", "re": "Severe recurrent nosebleeds, difficulty breathing, facial swelling"}, {"b": "head", "a": "ألم أذن (Ear Pain)", "e": "Ear Pain", "ga": "أطفال وبالغين", "ge": "Children and adults", "sa": "مسكن للألم (باراسيتامول أو إيبوبروفين) حسب الوزن مؤقتاً ومراجعة الطبيب لفحص طبلة الأذن", "se": "Weight-based pain reliever (Paracetamol or Ibuprofen) temporarily, consult doctor for otoscopic examination", "ra": "إفرازات أو صديد أو دم من الأذن، حمى شديدة مصاحبة، تورم خلف الأذن، استمرار الألم فوق يومين", "re": "Discharge, pus or blood from ear, high fever, swelling behind ear, pain lasting over 2 days"}, {"b": "head", "a": "حمى (Fever) - أطفال 3 أشهر إلى 12 سنة", "e": "Fever - Children 3 mo to 12 yr", "ga": "أطفال 3 أشهر - 12 سنة", "ge": "Children 3 months - 12 years", "sa": "باراسيتامول أو إيبوبروفين حسب الوزن بدقة مع سوائل كافية وملابس خفيفة (راجع حاسبة الجرعات)", "se": "Paracetamol or Ibuprofen accurately dosed by weight, adequate fluids, and light clothing (see dosage calculator)", "ra": "حمى فوق 3 أيام، تشنجات، طفح جلدي مع حمى، خمول شديد وصعوبة إيقاظ الطفل", "re": "Fever lasting over 3 days, febrile seizures, non-blanching rash with fever, extreme lethargy"}, {"b": "head", "a": "حمى (Fever) - رضع أقل من 3 أشهر", "e": "Fever - Infants under 3 months", "ga": "رضع أقل من 3 أشهر", "ge": "Infants under 3 months", "sa": "لا يُقترح أي دواء ذاتي إطلاقاً - التوجه الفوري لأقرب طوارئ أطفال", "se": "No self-medication recommended under any circumstance - go to pediatric emergency immediately", "ra": "أي حمى عند رضيع أقل من 3 أشهر تعتبر حالة طارئة تستدعي فحوصات دم فورية", "re": "Any fever in an infant under 3 months is a clinical emergency requiring immediate blood tests"}, {"b": "chest", "a": "حرقة المعدة والحموضة (Heartburn & Reflux)", "e": "Heartburn & Acid Reflux", "ga": "بالغين وأطفال فوق 12 سنة", "ge": "Adults and children over 12 years", "sa": "مضادات الحموضة القابلة للمضغ لتسكين فوري، تجنب الاستلقاء مباشرة بعد الأكل، تجنب الأطعمة الدسمة والحارة", "se": "Chewable antacids for rapid relief, avoid lying down after meals, reduce fatty and spicy foods", "ra": "ألم ضاغط أو عاصر بالصدر يمتد للذراع الأيسر أو الفك أو الظهر، مصحوب بتعرق بارد أو صعوبة تنفس (اشتباه جلطة قلبية - اتصل بالإسعاف فوراً)، صعوبة بلع، أو تقيؤ دموي", "re": "Crushing chest pain radiating to left arm/jaw/back with cold sweat or shortness of breath (suspected myocardial infarction - call ambulance!), dysphagia, or hematemesis"}, {"b": "chest", "a": "ضيق التنفس (Shortness of Breath - طوارئ)", "e": "Shortness of Breath (Emergency)", "ga": "جميع الأعمار", "ge": "All ages", "sa": "حالة طارئة تتطلب مراجعة فورية. لمرضى الربو المشخصين: أخذ بخاخ الإنقاذ الموصوف فوراً وفق الخطة الفردية والتوجه للطوارئ", "se": "Medical emergency requiring immediate clinical attention. Diagnosed asthma patients: take prescribed rescue inhaler immediately and head to emergency", "ra": "حالة طارئة تستدعي الإسعاف فوراً: ازرقاق الشفاه أو الأظافر، عدم القدرة على إكمال جملة، ألم صدري حاد، أزيز شديد مفاجئ، أو حساسية شديدة وتورم في الحلق", "re": "Immediate ambulance emergency: cyanosis (blue lips/nails), inability to speak full sentences, severe chest pain, acute stridor/wheezing, or anaphylaxis throat swelling"}, {"b": "chest", "a": "كحة / سعال (Cough) - فوق 6 سنوات", "e": "Cough - Over 6 years", "ga": "أطفال فوق 6 سنوات وبالغين", "ge": "Children over 6 years and adults", "sa": "غوايفينيزين للسعال مع بلغم، أو ديكستروميثورفان للسعال الجاف، والعسل للأطفال فوق سنة", "se": "Guaifenesin for productive cough, Dextromethorphan for dry cough, and honey for children over 1 year", "ra": "صعوبة تنفس، أزيز، ازرقاق، سعال مستمر فوق أسبوعين، خروج دم مع السعال", "re": "Difficulty breathing, wheezing, blue color, cough lasting over 2 weeks, hemoptysis (blood in sputum)"}, {"b": "chest", "a": "كحة عند أطفال أقل من 6 سنوات", "e": "Cough in children under 6 years", "ga": "أطفال أقل من 6 سنوات", "ge": "Children under 6 years", "sa": "لا تُستخدم أدوية السعال والبرد التجارية إطلاقاً - سوائل دافئة، عسل للأطفال فوق سنة، ومحلول ملحي للأنف", "se": "Never use OTC commercial cough syrups under 6 - warm fluids, honey for children over 1 year, and saline nasal spray", "ra": "صعوبة تنفس، صوت صفير أو شخير أثناء التنفس، حمى مرتفعة، رفض الرضاعة والشرب", "re": "Labored breathing, stridor or audible wheezing, high fever, refusal to feed or drink"}, {"b": "chest", "a": "سعال ونزلة برد (Cough & Cold)", "e": "Cough & Cold", "ga": "أطفال فوق سنتين وبالغين", "ge": "Children over 2 years and adults", "sa": "محلول ملحي للأنف، شرب سوائل دافئة، مسكنات ألم خفيفة (باراسيتامول) عند الحاجة", "se": "Saline nasal wash, warm fluids, mild analgesics (Paracetamol) as needed", "ra": "صعوبة تنفس، ألم حاد بالصدر، حمى مستمرة فوق 3 أيام، ازرقاق الشفاه", "re": "Labored breathing, sharp chest pain, fever lasting over 3 days, blue lips"}, {"b": "abdomen", "a": "عسر الهضم والانتفاخ (Indigestion & Bloating)", "e": "Indigestion & Bloating", "ga": "بالغين", "ge": "Adults", "sa": "مضادات الحموضة القابلة للمضغ، سيميثيكون للتخلص من الغازات، تقسيم الوجبات وتجنب المشروبات الغازية والتدخين", "se": "Chewable antacids, Simethicone for gas relief, smaller frequent meals, avoiding carbonated drinks and smoking", "ra": "ألم بطني شديد ومفاجئ، يرقان (اصفرار العين والجلد)، فقدان وزن سريع غير مبرر، براز أسود داكن", "re": "Sudden severe abdominal pain, jaundice, unexplained rapid weight loss, melena (black tarry stool)"}, {"b": "abdomen", "a": "مغص / ألم بطن عام (Colic/Abdominal Pain)", "e": "Colic / Abdominal Pain", "ga": "أطفال وبالغين", "ge": "Children and adults", "sa": "لا يُقترح مسكن قوي قبل تحديد السبب تجنباً لإخفاء تشخيص جراحي - راحة ومراقبة للحالات الخفيفة فقط", "se": "No strong pain relievers before diagnosis to avoid masking surgical conditions - rest and hydration for mild cases only", "ra": "ألم شديد متمركز أسفل يمين البطن (اشتباه زائدة دودية)، تصلب عضلات البطن كلوح خشبي، تقيؤ متكرر، دم بالبراز أو القيء", "re": "Severe localized lower right quadrant pain (suspected appendicitis), abdominal guarding/rigidity, repeated vomiting, blood in stool or vomit"}, {"b": "abdomen", "a": "القيء والغثيان (زوع - Vomiting)", "e": "Vomiting & Nausea", "ga": "جميع الأعمار", "ge": "All ages", "sa": "محلول إماهة فموية (ORS) برشفات صغيرة ومتكررة للوقاية من الجفاف. للحالات الشديدة: مراجعة الطبيب لتقييم الحاجة لأونداسيترون", "se": "Oral rehydration solution (ORS) in frequent small sips. For severe persistent cases: consult doctor for Ondansetron assessment", "ra": "قيء دموي أو بلون أخضر/أصفر صفراوي، علامات جفاف شديد، قيء مستمر مع خمول تام، صداع شديد أو بعد ضربة على الرأس", "re": "Hematemesis, bilious green/yellow vomit, severe dehydration, lethargy, or severe headache following head trauma"}, {"b": "abdomen", "a": "إسهال (Diarrhea)", "e": "Diarrhea", "ga": "جميع الأعمار", "ge": "All ages", "sa": "محلول إماهة فموية (ORS) لتعويض السوائل والأملاح المفقودة بعد كل نوبة إسهال، والابتعاد عن العصائر السكرية", "se": "Oral Rehydration Solution (ORS) to replace fluids and electrolytes after each episode, avoid sugary drinks", "ra": "دم في البراز، جفاف شديد (جفاف الفم، غؤور العينين، قلة التبول)، استمرار الإسهال أكثر من 48 ساعة عند الأطفال", "re": "Blood in stool (dysentery), severe dehydration (dry mucosa, sunken eyes, anuria), diarrhea persisting >48h in children"}, {"b": "abdomen", "a": "إمساك (Constipation)", "e": "Constipation", "ga": "أطفال وبالغين", "ge": "Children and adults", "sa": "زيادة شرب الماء والألياف الغذائية والنشاط البدني، واستخدام ملين (بيساكوديل للبالغين، أو لبوس غليسرين للرضع) عند الضرورة", "se": "Increase dietary fiber, water intake and physical activity; laxatives (Bisacodyl for adults, Glycerin for infants) when necessary", "ra": "ألم بطني حاد مفاجئ، تقيؤ، انتفاخ شديد مع عدم خروج غازات (اشتباه انسداد أمعاء)، دم في البراز", "re": "Acute severe abdominal pain, vomiting, obstipation (no gas/stool - suspected obstruction), hematochezia"}, {"b": "abdomen", "a": "المغص المعوي عند الرضع (Infantile Colic)", "e": "Infantile Colic", "ga": "رضع أقل من 4-5 أشهر", "ge": "Infants under 4-5 months", "sa": "طمأنة الأهل، تدليك بطن الرضيع بلطف، تجربة نقاط سيميثيكون بعد الرضاعة، وتعديل وضعية الإرضاع والتجشؤ", "se": "Reassure parents, gentle tummy massage, trial of Simethicone drops after feeds, upright feeding position and burping", "ra": "بكاء مستمر مع حمى، قيء صفراوي، دم بالبراز، توقف زيادة الوزن، أو خمول غير طبيعي", "re": "Inconsolable crying with fever, bilious vomiting, bloody stool, failure to thrive, abnormal lethargy"}, {"b": "skin", "a": "طفح جلدي (Skin Rash)", "e": "Skin Rash", "ga": "جميع الأعمار", "ge": "All ages", "sa": "لا يُقترح دواء ذاتي بدون تشخيص دقيق لسبب الطفح - يمكن استخدام كمادات باردة أو مرطبات خالية من العطور", "se": "No self-medication without professional etiology identification - cold compresses or fragrance-free emollients may soothe", "ra": "طفح مصحوب بحمى، طفح لا يختفي لونه عند الضغط عليه بزجاج شفاف (اشتباه عدوى سحائية)، صعوبة تنفس أو تورم بالوجه", "re": "Rash with fever, non-blanching petechial/purpuric rash (suspected meningococcemia), breathing difficulty, facial angioedema"}, {"b": "skin", "a": "حساسية الجلد (Skin Allergy & Hives)", "e": "Skin Allergy & Hives", "ga": "جميع الأعمار", "ge": "All ages", "sa": "هيدروكورتيزون كريم 1% موضعياً للحكة المحدودة + مضاد هيستامين فموي (سيتيريزين أو لوراتادين)", "se": "Topical Hydrocortisone 1% cream for localized itching + oral antihistamine (Cetirizine or Loratadine)", "ra": "تورم الوجه أو الشفاه أو اللسان، صعوبة بالتنفس أو البلع، بحة بالصوت، دوخة وهبوط ضغط (صدمة تأقية طارئة - اطلب الإسعاف فوراً)", "re": "Angioedema of face/lips/tongue, difficulty breathing or swallowing, hoarseness, hypotension (Anaphylaxis - call emergency immediately!)"}, {"b": "limbs", "a": "ألم وخشونة المفاصل (Joint Pain & Arthritis)", "e": "Joint Pain & Stiffness (Arthritis / Arthralgia)", "ga": "بالغين وكبار السن", "ge": "Adults & elderly", "sa": "ديكلوفيناك جل موضعي 1% أو باراسيتامول لتخفيف الألم مع كمادات دافئة للخشونة الصباحية وتجنب إجهاد المفصل", "se": "Topical Diclofenac 1% gel or oral Paracetamol for pain relief, warm compresses for morning stiffness, avoid joint strain", "ra": "احمرار وتورم ساخن وحاد بمفصل واحد مع حمى وقشعريرة (اشتباه التهاب مفصل إنتاني صديدي طارئ)، عدم القدرة على تحريك المفصل تماماً، أو تشوه مفاجئ", "re": "Acute hot red swollen joint with fever and chills (suspected septic arthritis emergency), total joint immobility, or sudden visible deformity"}, {"b": "limbs", "a": "الشد والتمزق العضلي والإجهاد (Muscle Strain & Cramps)", "e": "Muscle Strain, Spasms & Cramps", "ga": "أطفال فوق 12 سنة وبالغين", "ge": "Over 12 years & adults", "sa": "بروتوكول RICE في أول 48 ساعة (راحة، كمادات ثلج، رباط ضاغط، رفع الطرف) + لصقات تسكين أو جل موضعي + إيبوبروفين لتخفيف الالتهاب", "se": "RICE protocol in first 48 hours (Rest, Ice, Compression, Elevation) + menthol pain relief patches or gel + Ibuprofen for inflammation", "ra": "ألم حاد متزايد مع تورم قاسي وبرودة في القدم/الساق أو ازرقاق وخدر، تورم وألم شديد في ربلة الساق (بطة الساق) بعد سفر أو خمول (اشتباه جلطة وريدية DVT)", "re": "Compartment syndrome signs (severe unrelenting pain, pallor, pulselessness, paresthesia), unilateral calf swelling/tenderness (suspected DVT)"}, {"b": "limbs", "a": "آلام أسفل الظهر والفقرات (Lower Back Pain & Lumbago)", "e": "Lower Back Pain & Spine Strain", "ga": "بالغين", "ge": "Adults", "sa": "المحافظة على حركة خفيفة ومشي وتجنب الراحة التامة بالسرير + لصقات تسكين دافئة أو جل موضعي مسكن + باراسيتامول أو إيبوبروفين لفترة قصيرة", "se": "Maintain gentle activity and light walking, avoid prolonged bed rest + warm pain patches or topical gel + short course of Paracetamol or Ibuprofen", "ra": "فقدان التحكم في التبول أو التبرز، خدر وتنميل بمنطقة المقعدة والأعضاء التناسلية (متلازمة ذيل الفرس الطارئة Cauda Equina)، ضعف مفاجئ بسقوط القدم، ألم متصاعد مع حمى", "re": "Loss of bowel/bladder control, saddle anesthesia in groin/perineum (Cauda Equina Syndrome emergency), sudden foot drop, or back pain with fever"}, {"b": "limbs", "a": "التواء الأربطة والكدمات العظمية (Sprains & Bone Bruises)", "e": "Ligament Sprains & Bone Contusions", "ga": "جميع الأعمار", "ge": "All ages", "sa": "تثبيت المفصل برباط مطاطي داعم، كمادات ثلج 15-20 دقيقة، مسكن باراسيتامول أو جل موضعي مسكن، ورفع العضو المصاب", "se": "Supportive elastic bandage immobilization, ice compresses 15-20 min, Paracetamol or topical gel, elevate the limb", "ra": "عدم القدرة على الوقوف أو تحميل الوزن على الطرف نهائياً لأكثر من 4 خطوات (معايير أوتاوا للاشتباه بالكسر العظمي)، ألم حاد عند لمس العظم مباشرة، أو صوت فرقعة حاد وقت الإصابة", "re": "Inability to bear weight immediately and take 4 steps (Ottawa fracture criteria), exquisite bony tenderness, severe deformity, or audible snap/pop at injury"}]') as t(b text, a text, e text, ga text, ge text, sa text, se text, ra text, re text);
